create table magical_nine_turn
(
    id                   int auto_increment comment '主键id'
        primary key,
    stock_code           varchar(10)                         null comment '股票代码',
    stock_name           varchar(20)                         null comment '股票名称',
    signal_date          date                                null comment '信号日期',
    pre_nine_sum_change  decimal(16, 4)                      null comment '前9日累计涨跌',
    post_four_sum_change decimal(16, 4)                      null comment '后4日区间盈亏',
    hit_rate             decimal(16, 4)                      null comment '后4日区间盈亏',
    turn_type            varchar(10)                         null comment '九转类型：红九转、绿九转',
    create_time          timestamp default CURRENT_TIMESTAMP null comment '创建时间',
    create_user          varchar(20)                         null comment '创建人',
    update_time          timestamp                           null comment '更新时间',
    update_user          varchar(20)                         null comment '更新人'
)
    comment '神奇九转';

